"""Header lookup helpers."""


def get_header(headers, name, default=None):
    """Return a trimmed value for an exact key."""
    if name in headers:
        return headers[name].strip()
    return default

"""Header lookup helpers."""


def get_header(headers, name, default=None):
    """Return an untrimmed value for an ASCII case-insensitive key."""
    wanted = str(name).lower()
    for key, value in headers.items():
        if str(key).lower() == wanted:
            return value
    return default

